-- LOANSMEET production schema reference. backend/server.js also creates/migrates these tables automatically.
CREATE TABLE leads (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,mobile TEXT NOT NULL,email TEXT,city TEXT NOT NULL,loan_type TEXT NOT NULL,loan_amount INTEGER NOT NULL,monthly_income INTEGER NOT NULL,employment_type TEXT NOT NULL,existing_emi INTEGER DEFAULT 0,cibil_range TEXT,consent INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'New',notes TEXT DEFAULT '',dsa_id INTEGER,follow_up_date TEXT,disbursed_amount INTEGER DEFAULT 0,payout_percent REAL DEFAULT 0,expected_payout REAL DEFAULT 0,actual_payout REAL DEFAULT 0,payout_status TEXT DEFAULT 'Unpaid',payout_date TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE dsas (id INTEGER PRIMARY KEY AUTOINCREMENT,company TEXT NOT NULL,contact_person TEXT NOT NULL,mobile TEXT,email TEXT,loan_types TEXT DEFAULT '',active INTEGER NOT NULL DEFAULT 1,notes TEXT DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payouts (id INTEGER PRIMARY KEY AUTOINCREMENT,lead_id INTEGER NOT NULL,dsa_id INTEGER,loan_amount INTEGER DEFAULT 0,disbursed_amount INTEGER DEFAULT 0,payout_percent REAL DEFAULT 0,expected_payout REAL DEFAULT 0,actual_payout REAL DEFAULT 0,status TEXT DEFAULT 'Unpaid',payment_date TEXT,notes TEXT DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tickets (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,mobile TEXT,email TEXT,subject TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'New',assigned_staff TEXT DEFAULT '',follow_up_date TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE activity_logs (id INTEGER PRIMARY KEY AUTOINCREMENT,lead_id INTEGER,action TEXT NOT NULL,details TEXT DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE admin_audit (id INTEGER PRIMARY KEY AUTOINCREMENT,action TEXT NOT NULL,ip TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
